"""Original HIV chapter: diagnosis and antiretroviral principles, checked November 2026."""
from qbank_authoring import question,ref,finalize
DX=ref('CDC: HIV Diagnosis and Acute Infection in STI Treatment Guidance','https://www.cdc.gov/std/treatment-guidelines/hiv.htm')
AR=ref('NIH/DHHS: Initial Combination Antiretroviral Regimens, September 2026','https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-adult-and-adolescent-arv/what-start-initial-combination-regimens')
MO=ref('NIH: Plasma HIV RNA and CD4 Monitoring','https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-adult-and-adolescent-arv/plasma-hiv-1-rna-cd4-monitoring')
HB=ref('NIH: Hepatitis B/HIV Coinfection','https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-adult-and-adolescent-arv/coinfections-hepatitis-b-virus-hiv')
AB=ref('NIH: HLA-B*5701 Screening','https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-adult-and-adolescent-arv/hla-b-5701-screening')
UU=ref('CDC: Undetectable Equals Untransmittable','https://www.cdc.gov/global-hiv-tb/php/our-approach/undetectable-untransmittable.html')
IN=ref('NIH: Integrase Inhibitor Regimens','https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-adult-and-adolescent-arv/what-start-integrase-strand-transfer-inhibitor')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('A patient develops fever, pharyngitis, rash and generalized lymphadenopathy three weeks after a high-risk exposure. An antibody-only HIV test is negative. What is the best next step?', 'Test for HIV RNA together with an appropriate laboratory antigen/antibody assay',[
 ('Exclude HIV because the antibody-only result is negative','Seroconversion may not yet have occurred.'),('Wait six months before further testing despite the acute syndrome','Acute infection can be detected earlier with appropriate methods.'),('Use CD4 count alone to establish infection','CD4 count is not the diagnostic infection assay.')],
 'Acute HIV can precede detectable antibody', '**The diagnostic window differs among RNA, antigen and antibody tests.**',['A compatible exposure and acute syndrome warrant nucleic-acid assessment.','PrEP or PEP exposure can complicate early test interpretation.'], '**Confirm the diagnosis through the recommended testing pathway.**',['Arrange prompt linkage to treatment and prevention counseling.','Repeat testing when a very early or discordant result requires clarification.'],[['RNA','Can detect early infection'],['Antigen/antibody','Laboratory screening pathway'],['Antibody only','Can miss the acute window']],[DX],style='clinical_scenario')
q('A laboratory HIV-1/2 antigen/antibody screen is reactive, but the HIV-1/HIV-2 antibody differentiation assay is negative. Which test resolves possible acute HIV-1 infection?', 'An HIV-1 nucleic-acid test',[
 ('CD4 count','It assesses immune status rather than confirming the discordant result.'),('A routine bacterial blood culture','It does not detect HIV RNA.'),('Repeating only the same screening assay indefinitely','The algorithm requires a resolving nucleic-acid step.')],
 'A reactive screen is not the end of the diagnostic algorithm', '**Acute infection can produce antigen reactivity before differentiated antibodies appear.**',['A false-reactive initial screen is another possibility.','The nucleic-acid result helps distinguish these possibilities.'], '**Communicate clearly about preliminary versus confirmed results.**',['Interpret results with exposure timing and antiretroviral use.','Use specialist laboratory advice for persistent unusual discordance.'],[['Screen reactive','Requires supplemental assessment'],['Differentiation negative','Acute infection or false reactivity possible'],['Resolution','HIV-1 NAT']],[DX])
q('Which test is the principal marker of virological response to ART?', 'Plasma HIV RNA concentration',[
 ('CD4 count alone','It measures immune status and may recover differently from viral suppression.'),('Total leukocyte count','It is not a specific measure of HIV replication.'),('Persistence of HIV antibody reactivity','Antibodies generally remain detectable despite successful suppression.')],
 'Virological and immunological monitoring answer different questions', '**HIV RNA measures circulating viremia.**',['A suppressed value supports effective treatment.','Unexpected viremia requires assessment of adherence, interactions and resistance.'], '**Interpret trends rather than one isolated small fluctuation.**',['Low-level blips differ from persistent confirmed failure.','Monitor according to the clinical and guideline schedule.'],[['HIV RNA','Virological response'],['CD4','Immune function'],['Antibody','Not a treatment-response marker']],[MO])
q('What is the main clinical role of the CD4 count in a person with HIV?', 'Assessing immune impairment and helping determine opportunistic-infection prevention needs',[
 ('Measuring HIV resistance mutations','Genotypic testing addresses resistance.'),('Confirming sustained sexual nontransmissibility independently of viral load','That conclusion relies on sustained viral suppression.'),('Replacing HIV diagnostic testing in an unconfirmed case','CD4 count is not a specific diagnostic test for HIV.')],
 'The degree of cellular immunodeficiency changes the differential', '**Lower CD4 counts increase vulnerability to selected opportunistic conditions.**',['Thresholds are interpreted with ART status and viral suppression.','A specific infection can occur outside its typical count range.'], '**Use CD4 information to guide prevention and diagnostic suspicion.**',['Do not rely solely on a count when a compatible illness is present.','Effective ART is the central long-term immune-restoring intervention.'],[['CD4','Immune risk'],['HIV RNA','Viral control'],['Genotype','Drug-resistance information']],[MO])
q('When should ART generally be offered to a person with confirmed HIV infection?', 'As soon as possible, regardless of baseline CD4 count, with selected opportunistic-infection timing exceptions',[
 ('Only after CD4 falls below 200','Modern treatment is not restricted to advanced immunodeficiency.'),('Only when symptoms appear','Asymptomatic people benefit from treatment.'),('Always immediately in cryptococcal meningitis without considering IRIS risk','CNS cryptococcosis is an important timing exception.')],
 'Early treatment benefits health and reduces transmission', '**ART is recommended for all people with HIV.**',['Baseline assessment guides a safe effective regimen.','Most treatment should not wait for progression to an AIDS-defining illness.'], '**Recognize conditions requiring coordinated timing.**',['Cryptococcal and TB meningitis need specific guidance.','Address access, adherence and drug interactions from the start.'],[['General principle','Prompt ART'],['CD4','Not a reason to defer until low'],['Exceptions','Selected CNS opportunistic infections']],[AR])
q('For most ART-naive adults without relevant resistance or complicating conditions, which approach is a recommended initial regimen category?', 'A bictegravir- or dolutegravir-based regimen with an appropriate active backbone',[
 ('NRTI monotherapy','It is not adequate suppressive HIV treatment.'),('A protease inhibitor without an active combination solely to minimize pill count','An effective suppressive regimen is required.'),('An antibiotic regimen directed at opportunistic bacteria instead of ART','That does not suppress HIV replication.')],
 'Initial ART balances potency, resistance barrier and tolerability', '**Second-generation integrase inhibitor regimens are preferred for many patients.**',['Check prior PrEP exposure and relevant resistance risk.','HBV status, renal function, pregnancy and interactions influence the specific choice.'], '**Select a complete regimen rather than one active drug.**',['Some validated two-drug regimens are suitable in defined circumstances.','Rapid-start choices must account for information not yet available.'],[['Anchor','Often BIC or DTG'],['Selection','Resistance and comorbidities'],['Goal','Durable complete suppression']],[AR])
q('A person has chronic HBV/HIV coinfection and can use tenofovir. Which ART backbone principle is preferred?', 'Include TAF or TDF together with FTC or 3TC as part of a fully suppressive HIV regimen',[
 ('Use lamivudine alone as the only HBV-active drug indefinitely','HBV resistance develops readily with that approach.'),('Use DTG/3TC alone without adding effective HBV therapy','It does not provide the preferred dual HBV-active backbone.'),('Stop all HBV-active agents whenever HIV RNA becomes undetectable','Withdrawal can cause HBV reactivation and hepatic flare.')],
 'One regimen must address two persistent viral infections', '**Tenofovir plus FTC or 3TC provides two HBV-active components.**',['The full regimen must also adequately suppress HIV.','Renal and bone risks help guide TAF versus TDF selection.'], '**Maintain HBV treatment when changing ART.**',['If tenofovir cannot be used, specialist alternative HBV therapy is needed alongside suppressive ART.','Monitor for hepatitis flares after interruptions.'],[['Backbone','Tenofovir plus FTC or 3TC'],['Avoid','Single low-barrier HBV-active drug alone'],['Switching','Preserve effective HBV treatment']],[HB],style='clinical_scenario')
q('Which statement correctly reflects the September 2026 NIH update on initial dolutegravir/lamivudine?', 'It can be used regardless of baseline HIV RNA when 3TC resistance is excluded and chronic HBV absence is documented',[
 ('A baseline HIV RNA above 500,000 always excludes it under the September 2026 update','The updated recommendation removed that viral-load restriction under the stated conditions.'),('It is appropriate before HBV status and 3TC susceptibility are known in every rapid start','Those conditions still matter.'),('It adequately treats chronic HBV coinfection without additional therapy','That remains an important limitation.')],
 'Regimen eligibility changes as evidence and guidelines evolve', '**The 2026 update broadens the baseline viral-load criterion.**',['Document absence of chronic HBV.','Ensure no genotypic resistance to lamivudine.'], '**Do not transfer this change to situations lacking required information.**',['Select a suitable rapid-start regimen when results are pending.','Prior exposure and adherence considerations still require assessment.'],[['Viral load','No baseline ceiling in this updated recommendation'],['Resistance','Exclude 3TC resistance'],['HBV','Document absence of chronic infection']],[AR])
q('Which pharmacogenetic test should be checked before an abacavir-containing regimen?', 'HLA-B*5701',[
 ('HLA-B*5801','This is relevant to allopurinol severe cutaneous reactions.'),('G6PD activity','This is important for selected oxidant medicines but not the abacavir-specific genetic risk.'),('TPMT activity','It guides selected thiopurine treatment rather than abacavir hypersensitivity risk.')],
 'A specific HLA association predicts a serious drug reaction', '**HLA-B*5701 positivity increases abacavir hypersensitivity risk.**',['Use an alternative when positive.','A previous suspected abacavir hypersensitivity reaction is a reason not to rechallenge.'], '**Counsel about systemic hypersensitivity symptoms.**',['Fever, rash and gastrointestinal or respiratory symptoms may occur.','A negative genotype does not eliminate the need for clinical vigilance.'],[['Test','HLA-B*5701'],['Positive','Avoid abacavir'],['Prior reaction','Do not rechallenge']],[AB])
q('A patient taking TDF develops proximal tubular dysfunction and declining bone mineral density. Which principle is correct?', 'Review tenofovir-related toxicity and consider a suitable alternative while preserving HIV and any HBV suppression',[
 ('Abruptly stop the whole regimen without arranging effective replacement','This risks viral rebound and HBV flare if coinfected.'),('Assume HIV suppression excludes drug toxicity','Effective treatment can still have adverse effects.'),('Treat only the creatinine number without assessing tubular losses','Proximal tubular dysfunction requires a broader assessment.')],
 'Antiretroviral selection includes long-term organ safety', '**TDF can cause renal tubular and bone adverse effects.**',['TAF generally produces lower systemic tenofovir exposure.','Other causes of renal and bone disease still require evaluation.'], '**Design the switch around resistance and coinfection.**',['Maintain a fully suppressive regimen.','Do not inadvertently remove effective HBV coverage.'],[['TDF','Renal tubular and bone concerns'],['Alternative','Patient-specific regimen review'],['Switch safety','Preserve HIV/HBV activity']],[AR,HB],style='clinical_scenario')
q('Why can polyvalent-cation antacids or supplements reduce oral integrase-inhibitor exposure?', 'Chelation in the gastrointestinal tract can reduce drug absorption',[
 ('They always induce irreversible viral resistance directly','Resistance is not their direct chemical action.'),('They specifically neutralize HIV antibodies','That is unrelated to the absorption interaction.'),('They uniformly increase drug absorption regardless of timing or food','The interaction is product- and timing-dependent.')],
 'An avoidable administration interaction can undermine an effective regimen', '**Calcium, iron, magnesium and aluminum can interact with INSTIs.**',['The instructions vary by drug, product and food conditions.','A medication review must include over-the-counter products.'], '**Use the exact regimen’s timing guidance.**',['Do not assume one separation interval applies to every combination.','Check interactions when unexpected viremia develops.'],[['Mechanism','Chelation'],['Consequence','Reduced absorption'],['Prevention','Drug-specific administration instructions']],[IN])
q('What does sustained undetectable HIV RNA on effective ART mean for sexual transmission?', 'It prevents sexual transmission of HIV while suppression is maintained',[
 ('It cures HIV and permits routine discontinuation of ART','The viral reservoir persists and treatment must continue.'),('It prevents every other sexually transmitted infection','U=U concerns HIV sexual transmission.'),('It proves zero risk through every possible exposure route regardless of adherence','The established U=U conclusion has a defined scope and requires maintained suppression.')],
 'Treatment is also a powerful prevention intervention', '**U=U applies to sexual transmission with sustained viral suppression.**',['Adherence and ongoing monitoring maintain the conditions for protection.','The person still needs continuing HIV care.'], '**Explain the scope accurately and without stigma.**',['Discuss other STI prevention and reproductive goals as appropriate.','A single old undetectable result does not document ongoing suppression after treatment interruption.'],[['Scope','Sexual HIV transmission'],['Requirement','Maintained viral suppression'],['Still needed','ART and appropriate ongoing care']],[UU])

if __name__=='__main__':print('HIV diagnosis and ART: '+str(len(rows))+' questions drafted')
